$q$;
  -- Marcadores: @@Dn@@ = lunes de W-3 + n dias; @@U@@ = la cuenta.
  FOR i IN -35..91 LOOP
    v_sql := replace(v_sql, '@@D' || i || '@@', to_char(v_w3 + i, 'YYYY-MM-DD'));
  END LOOP;
  v_sql := replace(v_sql, '@@U@@', v_user::text);
  IF position('@@' IN v_sql) > 0 THEN
    RAISE EXCEPTION 'DEMO: marcador sin sustituir';
  END IF;
  EXECUTE v_sql;
  RAISE NOTICE 'DEMO 04 aplicado a la cuenta % (weekly_training_plans=2, planned_workouts=10, planned_workout_exercises=60, workout_sessions=10, workout_session_exercises=60, weekly_user_metrics=2, plan_adaptation_attempts=2, user_interventions=2)', v_user;
END
$demo$;
